import{_ as t,o as e,c as n,am as i}from"./chunks/framework._FJXuPhs.js";const m=JSON.parse('{"title":"Windows服务安装——RabbitMQ","description":"","frontmatter":{"title":"Windows服务安装——RabbitMQ","excerpt":"摘要","date":"2025-03-30 16:55:37","updated":"2025-03-30 16:55:37"},"headers":[],"relativePath":"中间件/中间件 - 消息队列/MQ RabbitMQ/Windows服务安装——RabbitMQ.md","filePath":"中间件/中间件 - 消息队列/MQ RabbitMQ/Windows服务安装——RabbitMQ.md","lastUpdated":null}'),s={name:"中间件/中间件 - 消息队列/MQ RabbitMQ/Windows服务安装——RabbitMQ.md"};function r(p,a,o,b,l,d){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h3 id="windows下-rabbitmq-的安装" tabindex="-1">Windows下 RabbitMQ 的安装 <a class="header-anchor" href="#windows下-rabbitmq-的安装" aria-label="Permalink to &quot;Windows下 RabbitMQ 的安装&quot;">​</a></h3><p>RabbitMQ服务端代码是使用并发式语言Erlang编写的，安装Rabbit MQ的前提是需要安装一下Erlang</p><p>Erlang 下载地址： <a href="https://www.erlang.org/downloads" target="_blank" rel="noreferrer">https://www.erlang.org/downloads</a></p><p>环境变量配置</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ERLANG_HOME</span></span>
<span class="line"><span>%ERLANG_HOME%\\bin</span></span></code></pre></div><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20231203233950.png" alt="image.png"></p><p>打开 cmd 输入 erl -version 出现版本号即安装成功</p><blockquote><p>RabbitMQ</p></blockquote><p>rabbitmq 下载地址： <a href="https://www.rabbitmq.com/download.html" target="_blank" rel="noreferrer">https://www.rabbitmq.com/download.html</a></p><p>下载进行安装操作。</p><p>CMD 进入终端 进入到安装目录 执行 rabbitmq-plugins enable rabbitmq_management 命令安装管理页面的插件，</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20231203234341.png" alt="image.png"></p><p>启动rabbitMQ服务：rabbitmq-service.bat start</p><p>双击 rabbitmq-service.bat 即完成安装。（关闭的话手动在服务列表进行关闭一下）</p><p>登陆： <a href="http://127.0.0.1:15672/" target="_blank" rel="noreferrer">http://127.0.0.1:15672/</a></p><p>初始的默认用户及密码都是 <code>guest</code> ， 输入后即可登录</p>`,16)])])}const _=t(s,[["render",r]]);export{m as __pageData,_ as default};
